import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh } = THREE;

  const group = new Group();

  // Dimensions for a horizontal list row
  const width = 3.0;
  const height = 0.4;
  const geo = new PlaneGeometry(width, height);
  const mat = new MeshBasicNodeMaterial({ color: '#e8ecf2' }); // paper color fallback
  const mesh = new Mesh(geo, mat);
  group.add(mesh);

  // Load texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      mat.map = tex;
      mat.needsUpdate = true;
    });
  }

  // Hover and click handlers (compatible with Prism event system)
  let hoverTimeline = null;
  let pressTimeline = null;

  const handlers = {
    hover: (event) => {
      if (event.type === 'pointerover' || event.type === 'pointerenter') {
        if (hoverTimeline) hoverTimeline.kill();
        hoverTimeline = gsap.timeline({ paused: true });
        hoverTimeline.to(mesh.position, { y: 0.075, duration: 0.3, ease: 'power2.out' });
        hoverTimeline.play();
      } else if (event.type === 'pointerout' || event.type === 'pointerleave') {
        if (hoverTimeline) hoverTimeline.kill();
        hoverTimeline = gsap.timeline({ paused: true });
        hoverTimeline.to(mesh.position, { y: 0, duration: 0.3, ease: 'power2.out' });
        hoverTimeline.play();
      }
    },
    click: () => {
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.timeline({ paused: true });
      pressTimeline.to(mesh.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(1.2)' });
      pressTimeline.to(mesh.scale, { x: 1, y: 1, duration: 0.2, ease: 'power2.out' }, '+=0.08');
      pressTimeline.play();
      ctx.emit('hub-collection.select', {});
    }
  };

  group.userData.handlers = handlers;

  // Cleanup
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    geo.dispose();
    mat.dispose();
    if (mat.map) mat.map.dispose();
    mesh.removeFromParent();
  };

  return group;
}
